    hilog.info(0x0000, 'testTag', `rootNode id: ${this.rootNode?.getId()}`);
    this.notifyRedraw();
  }

  dispose(): void {
    // 下面这些实际不调用也不会影响node的释放
    this.canvasNode?.clearChildren()
    this.canvasNode?.dispose()
    this.canvasNode = null
  }
}


@Component
struct CanvasPage {
  @Prop pageId: string = `oh_canvas_${CanvasPage.globalPageIndex++}`
  private static globalPageIndex: number = 0;
  private canvasNodeController: CanvasNodeController = new CanvasNodeController(this.getUIContext());
  private static pageIsShowing: boolean = false;
  private static canDestroyPicture: boolean = true;

  build() {
    Stack() {
      NodeContainer(this.canvasNodeController)
        .id(this.pageId)
        .width("100%")
        .height("100%")
        .onAreaChange((oldValue: Area, newValue: Area) => {
          let info = `Ace: on area change, oldValue is ${JSON.stringify(oldValue)} value is ${JSON.stringify(newValue)}`
          this.canvasNodeController.onResize({
            width: newValue.width as number,
            height: newValue.height as number,
          })
        })
    }
  }

  aboutToAppear() {
    nativeCanvas.nativeRegisterNodeConstructor(CanvasRenderNode);
    nativeCanvas.nativeRegisterNodeStatusModifyConstructor(NodeStatusModify);
    nativeCanvas.nativeSetPixelRatio(vp2px(1.0));
    this.loadRenderNode();

    if (CanvasPage.pageIsShowing) {
      CanvasPage.canDestroyPicture = false;
    }
    CanvasPage.pageIsShowing = true;
  }


  private tsFrameNode: FrameNode[] = []
  private videoBuildNode: BuilderNode<[ParamsInterface]> =
    new BuilderNode<[ParamsInterface]>(this.getUIContext());

  private textBuildNode: BuilderNode<[string]> =
    new BuilderNode<[string]>(this.getUIContext());

  private webBuildNode: BuilderNode<[string]> =
    new BuilderNode<[string]>(this.getUIContext());

  resource: Resource = $rawfile('Butterfly-209.mp4')
  videoString: string = "Video From ArkUI"

  loadRenderNode() {
    if (this.tsFrameNode.length == 0) {

      this.videoBuildNode.build(wrapBuilder<[ParamsInterface]>(buildVideo),
        {resource: this.resource, str: this.videoString}, { nestingBuilderSupported: true });

      let frameNode1 = new FrameNode(this.getUIContext());
      frameNode1.appendChild(this.videoBuildNode.getFrameNode())
      this.tsFrameNode[0] = frameNode1;

      nativeCanvas.nativeAddExternalNode(frameNode1.getRenderNode());
      this.canvasNodeController.addBuildNode(this.videoBuildNode);


      this.textBuildNode.build(wrapBuilder<[string]>(buildText), "Text from ArkUI", { nestingBuilderSupported: true });

      let frameNode2 = new FrameNode(this.getUIContext());
      frameNode2.appendChild(this.textBuildNode.getFrameNode())
      this.tsFrameNode[1] = frameNode2;

      nativeCanvas.nativeAddExternalNode(frameNode2.getRenderNode());
      this.canvasNodeController.addBuildNode(this.textBuildNode);


      this.webBuildNode.build(wrapBuilder<[string]>(buildWeb), "www.baidu.com", { nestingBuilderSupported: true });

      let frameNode3 = new FrameNode(this.getUIContext());
      frameNode3.appendChild(this.webBuildNode.getFrameNode())
      this.tsFrameNode[1] = frameNode3;

      nativeCanvas.nativeAddExternalNode(frameNode3.getRenderNode());
      this.canvasNodeController.addBuildNode(this.webBuildNode);

    }
  }

  aboutToDisappear() {
    nativeCanvas.nativeDestroyAllNodeCache();
    if (CanvasPage.canDestroyPicture) {
    } else {
      console.warn(`warning destroy node: page is appear twice but no disappear--picture will be delete after page appear`)
    }
    CanvasPage.canDestroyPicture = true;
    CanvasPage.pageIsShowing = false;
    this.canvasNodeController.dispose();
  }
}

